static NSMutableDictionary<NSNumber*,id>* refs;
static NSString* snapshotId;
static NSString* snapshotApp;
static int nextId;
static NSTimeInterval inspectDeadline;
static NSArray* snapshotWindows;
static id Attr(AXUIElementRef e, CFStringRef key) { CFTypeRef v=nullptr; if(AXUIElementCopyAttributeValue(e,key,&v)!=kAXErrorSuccess||!v)return nil;return CFBridgingRelease(v); }
static NSString* Str(id v) { if ([v isKindOfClass:[NSString class]]) return v; if ([v isKindOfClass:[NSNumber class]]) return [v stringValue]; return @""; }
static bool IsSecure(AXUIElementRef e) { return [Str(Attr(e,kAXRoleAttribute)) isEqualToString:@"AXSecureTextField"] || [Str(Attr(e,kAXSubroleAttribute)) isEqualToString:@"AXSecureTextField"]; }
static NSDictionary* ElementFrame(AXUIElementRef e) { CGPoint p={};CGSize s={};id a=Attr(e,kAXPositionAttribute),b=Attr(e,kAXSizeAttribute);if(a&&CFGetTypeID((__bridge CFTypeRef)a)==AXValueGetTypeID())AXValueGetValue((__bridge AXValueRef)a,kAXValueTypeCGPoint,&p);if(b&&CFGetTypeID((__bridge CFTypeRef)b)==AXValueGetTypeID())AXValueGetValue((__bridge AXValueRef)b,kAXValueTypeCGSize,&s);return @{@"x":@(p.x),@"y":@(p.y),@"width":@(s.width),@"height":@(s.height)}; }
static NSString* StringArg(napi_env env,napi_value value) { size_t n=0;napi_get_value_string_utf8(env,value,nullptr,0,&n);std::string s(n+1,'\0');napi_get_value_string_utf8(env,value,s.data(),s.size(),&n);return [[NSString alloc]initWithBytes:s.data() length:n encoding:NSUTF8StringEncoding]; }
static napi_value Json(napi_env env,id value) { NSData* data=[NSJSONSerialization dataWithJSONObject:value options:0 error:nil];napi_value result;napi_create_string_utf8(env,(const char*)data.bytes,data.length,&result);return result; }
static void Walk(AXUIElementRef e,int depth,NSMutableArray* out,NSMutableSet* visited) {
 if(depth>14||out.count>=450||NSDate.date.timeIntervalSince1970>inspectDeadline)return;NSString* identity=[NSString stringWithFormat:@"%p",e];if([visited containsObject:identity])return;[visited addObject:identity];
 NSString* role=Str(Attr(e,kAXRoleAttribute));int i=++nextId;refs[@(i)]=(__bridge id)e;NSString* value=IsSecure(e)?@"[密码不读取]":Str(Attr(e,kAXValueAttribute));if(value.length>1400)value=[value substringToIndex:1400];
 NSDictionary* frame=ElementFrame(e);
 [out addObject:@{@"id":@(i),@"depth":@(depth),@"role":role,@"subrole":Str(Attr(e,kAXSubroleAttribute)),@"enabled":Attr(e,kAXEnabledAttribute)?:@YES,@"title":Str(Attr(e,kAXTitleAttribute)),@"description":Str(Attr(e,kAXDescriptionAttribute)),@"value":value,@"frame":frame}];
 // Closed menus contain hundreds of offscreen items; their titles remain available for opening.
 if([role isEqualToString:@"AXMenu"]&&([frame[@"width"] doubleValue]<=0||[frame[@"height"] doubleValue]<=0))return;
 id children=Attr(e,kAXChildrenAttribute);if([children isKindOfClass:[NSArray class]])for(id child in children)Walk((__bridge AXUIElementRef)child,depth+1,out,visited);
}
static id Run(NSDictionary* r) {
 NSString* action=r[@"action"];
 if([action isEqualToString:@"status"])return @{@"accessibility":@(AXIsProcessTrusted()),@"screenRecording":@(CGPreflightScreenCaptureAccess())};
 if([action isEqualToString:@"request_accessibility"]){AXIsProcessTrustedWithOptions((__bridge CFDictionaryRef)@{(__bridge NSString*)kAXTrustedCheckOptionPrompt:@YES});return @{@"requested":@YES};}
 if([action isEqualToString:@"request_screen"]){CGRequestScreenCaptureAccess();return @{@"requested":@YES};}
 if([action isEqualToString:@"apps"]){NSMutableArray* a=[NSMutableArray array];for(NSRunningApplication* app in NSWorkspace.sharedWorkspace.runningApplications)if(app.activationPolicy==NSApplicationActivationPolicyRegular)[a addObject:@{@"name":app.localizedName?:@"",@"bundleId":app.bundleIdentifier?:@"",@"pid":@(app.processIdentifier),@"active":@(app.active)}];return a;}
 NSString* bundle=r[@"app"];if(![bundle isKindOfClass:[NSString class]]||bundle.length==0)@throw [NSException exceptionWithName:@"Input" reason:@"请指定应用 bundleId，先用 apps 查看" userInfo:nil];
 if([action isEqualToString:@"launch"]){NSURL* url=[NSWorkspace.sharedWorkspace URLForApplicationWithBundleIdentifier:bundle];if(!url)@throw [NSException exceptionWithName:@"App" reason:@"应用尚未安装" userInfo:nil];[NSWorkspace.sharedWorkspace openApplicationAtURL:url configuration:NSWorkspaceOpenConfiguration.configuration completionHandler:nil];return @{@"opened":bundle};}
 NSArray* running=[NSRunningApplication runningApplicationsWithBundleIdentifier:bundle];NSRunningApplication* app=running.firstObject;if(!app)@throw [NSException exceptionWithName:@"App" reason:@"应用未运行，先 launch" userInfo:nil];
 if(!AXIsProcessTrusted())@throw [NSException exceptionWithName:@"Permission" reason:@"请在工作台的电脑权限中开启辅助功能" userInfo:nil];
 AXUIElementRef application=AXUIElementCreateApplication(app.processIdentifier);AXUIElementSetMessagingTimeout(application,0.25);
 if([action isEqualToString:@"inspect"]){refs=[NSMutableDictionary dictionary];nextId=0;inspectDeadline=NSDate.date.timeIntervalSince1970+6;snapshotId=NSUUID.UUID.UUIDString;snapshotApp=bundle;NSMutableArray* nodes=[NSMutableArray array];Walk(application,0,nodes,[NSMutableSet set]);CFRelease(application);NSMutableArray* windows=[NSMutableArray array];for(NSDictionary* w in CFBridgingRelease(CGWindowListCopyWindowInfo(kCGWindowListOptionOnScreenOnly,kCGNullWindowID)))if([w[(id)kCGWindowOwnerPID] intValue]==app.processIdentifier&&[w[(id)kCGWindowLayer] intValue]==0)[windows addObject:@{@"id":w[(id)kCGWindowNumber],@"title":w[(id)kCGWindowName]?:@"",@"bounds":w[(id)kCGWindowBounds]?:@{}}];snapshotWindows=windows;return @{@"app":bundle,@"snapshotId":snapshotId,@"nodes":nodes,@"windows":windows,@"truncated":@(nodes.count>=450||NSDate.date.timeIntervalSince1970>inspectDeadline)};}
 CFRelease(application);
 if(![r[@"snapshotId"] isEqual:snapshotId]||![bundle isEqual:snapshotApp])@throw [NSException exceptionWithName:@"Stale" reason:@"界面快照已过期，先重新 inspect" userInfo:nil];
 [app activateWithOptions:NSApplicationActivateAllWindows];
 NSNumber* nodeId=r[@"element"];AXUIElementRef element=nodeId?(__bridge AXUIElementRef)refs[nodeId]:nullptr;
 if([action isEqualToString:@"click"]){if(!element)@throw [NSException exceptionWithName:@"Element" reason:@"请使用本次快照里的元素编号" userInfo:nil];AXError e=AXUIElementPerformAction(element,kAXPressAction);if(e!=kAXErrorSuccess){NSDictionary* f=ElementFrame(element);double x=[f[@"x"] doubleValue]+[f[@"width"] doubleValue]/2,y=[f[@"y"] doubleValue]+[f[@"height"] doubleValue]/2;if([f[@"width"]doubleValue]<=0)@throw [NSException exceptionWithName:@"Element" reason:@"元素不能点击" userInfo:nil];for(int down=1;down>=0;down--){CGEventRef event=CGEventCreateMouseEvent(nullptr,down?kCGEventLeftMouseDown:kCGEventLeftMouseUp,CGPointMake(x,y),kCGMouseButtonLeft);CGEventPost(kCGHIDEventTap,event);CFRelease(event);}}}
 else if([action isEqualToString:@"type_text"]){NSString* text=r[@"text"];if(![text isKindOfClass:[NSString class]]||text.length>12000)@throw [NSException exceptionWithName:@"Input" reason:@"文本长度无效" userInfo:nil];if(element){NSString* role=Str(Attr(element,kAXRoleAttribute));if(IsSecure(element))@throw [NSException exceptionWithName:@"Sensitive" reason:@"密码框由你本人输入" userInfo:nil];AXUIElementSetAttributeValue(element,kAXFocusedAttribute,kCFBooleanTrue);if(AXUIElementSetAttributeValue(element,kAXValueAttribute,(__bridge CFTypeRef)text)!=kAXErrorSuccess)@throw [NSException exceptionWithName:@"Element" reason:@"此控件不支持写入文本" userInfo:nil];}else{std::vector<UniChar> chars(text.length);[text getCharacters:chars.data() range:NSMakeRange(0,text.length)];AXUIElementRef system=AXUIElementCreateSystemWide();id focused=Attr(system,kAXFocusedUIElementAttribute);CFRelease(system);if(focused&&IsSecure((__bridge AXUIElementRef)focused))@throw [NSException exceptionWithName:@"Sensitive" reason:@"密码框由你本人输入" userInfo:nil];for(int down=1;down>=0;down--){CGEventRef e=CGEventCreateKeyboardEvent(nullptr,0,down);CGEventKeyboardSetUnicodeString(e,chars.size(),chars.data());CGEventPost(kCGHIDEventTap,e);CFRelease(e);}}}
 else if([action isEqualToString:@"click_at"]||[action isEqualToString:@"drag"]){
 double x=[r[@"x"] doubleValue],y=[r[@"y"] doubleValue],tx=[r[@"toX"] doubleValue],ty=[r[@"toY"] doubleValue];bool valid=false,endValid=false;
 for(NSDictionary* window in snapshotWindows){NSDictionary* b=window[@"bounds"];double bx=[b[@"X"] doubleValue],by=[b[@"Y"] doubleValue],bw=[b[@"Width"] doubleValue],bh=[b[@"Height"] doubleValue];if(std::isfinite(x)&&std::isfinite(y)&&x>=bx&&x<=bx+bw&&y>=by&&y<=by+bh)valid=true;if(std::isfinite(tx)&&std::isfinite(ty)&&tx>=bx&&tx<=bx+bw&&ty>=by&&ty<=by+bh)endValid=true;}
 if(!valid||([action isEqualToString:@"drag"]&&!endValid))@throw [NSException exceptionWithName:@"Bounds" reason:@"鼠标坐标必须位于当前应用快照的可见窗口内" userInfo:nil];
 CGEventRef down=CGEventCreateMouseEvent(nullptr,kCGEventLeftMouseDown,CGPointMake(x,y),kCGMouseButtonLeft);CGEventPost(kCGHIDEventTap,down);CFRelease(down);
 if([action isEqualToString:@"drag"]){for(int step=1;step<=20;step++){CGEventRef move=CGEventCreateMouseEvent(nullptr,kCGEventLeftMouseDragged,CGPointMake(x+(tx-x)*step/20,y+(ty-y)*step/20),kCGMouseButtonLeft);CGEventPost(kCGHIDEventTap,move);CFRelease(move);usleep(12000);}}else{tx=x;ty=y;}
 CGEventRef up=CGEventCreateMouseEvent(nullptr,kCGEventLeftMouseUp,CGPointMake(tx,ty),kCGMouseButtonLeft);CGEventPost(kCGHIDEventTap,up);CFRelease(up);
 }
 else if([action isEqualToString:@"press_key"]){NSDictionary* keys=@{@"return":@36,@"enter":@36,@"tab":@48,@"escape":@53,@"space":@49,@"backspace":@51,@"delete":@117,@"left":@123,@"right":@124,@"up":@126,@"down":@125,@"a":@0,@"c":@8,@"v":@9,@"x":@7,@"z":@6,@"s":@1,@"o":@31,@"n":@45,@"w":@13,@"l":@37,@"f":@3,@"q":@12,@"e":@14,@"r":@15,@"t":@17,@"y":@16,@"u":@32,@"i":@34,@"p":@35,@"d":@2,@"g":@5,@"h":@4,@"j":@38,@"k":@40,@"b":@11,@"m":@46,@"0":@29,@"1":@18,@"2":@19,@"3":@20,@"4":@21,@"5":@23,@"6":@22,@"7":@26,@"8":@28,@"9":@25};NSArray* parts=[Str(r[@"key"]).lowercaseString componentsSeparatedByString:@"+"];NSNumber* code=keys[parts.lastObject];if(!code)@throw [NSException exceptionWithName:@"Key" reason:@"不支持此按键组合" userInfo:nil];CGEventFlags flags=0;for(NSString* part in parts){if([part isEqual:@"cmd"]||[part isEqual:@"super"])flags|=kCGEventFlagMaskCommand;if([part isEqual:@"ctrl"])flags|=kCGEventFlagMaskControl;if([part isEqual:@"shift"])flags|=kCGEventFlagMaskShift;if([part isEqual:@"alt"])flags|=kCGEventFlagMaskAlternate;}for(int down=1;down>=0;down--){CGEventRef e=CGEventCreateKeyboardEvent(nullptr,code.unsignedShortValue,down);CGEventSetFlags(e,flags);CGEventPost(kCGHIDEventTap,e);CFRelease(e);}}
 else if([action isEqualToString:@"scroll"]){int amount=[r[@"amount"] intValue];amount=MAX(-1200,MIN(1200,amount));NSDictionary* b=[snapshotWindows.firstObject objectForKey:@"bounds"];if(b){CGPoint center=CGPointMake([b[@"X"] doubleValue]+[b[@"Width"] doubleValue]/2,[b[@"Y"] doubleValue]+[b[@"Height"] doubleValue]/2);CGEventRef move=CGEventCreateMouseEvent(nullptr,kCGEventMouseMoved,center,kCGMouseButtonLeft);CGEventPost(kCGHIDEventTap,move);CFRelease(move);}CGEventRef e=CGEventCreateScrollWheelEvent(nullptr,kCGScrollEventUnitPixel,1,amount);CGEventPost(kCGHIDEventTap,e);CFRelease(e);}
 else @throw [NSException exceptionWithName:@"Action" reason:@"未知电脑操作" userInfo:nil];
 snapshotId=nil;return @{@"done":@YES,@"next":@"重新 inspect 获取操作后的界面"};
}
static napi_value Request(napi_env env,napi_callback_info info){@autoreleasepool{size_t n=1;napi_value arg;napi_get_cb_info(env,info,&n,&arg,nullptr,nullptr);@try{if(n!=1)return Json(env,@{@"error":@"请求无效"});NSString* text=StringArg(env,arg);NSDictionary* r=[NSJSONSerialization JSONObjectWithData:[text dataUsingEncoding:NSUTF8StringEncoding] options:0 error:nil];if(![r isKindOfClass:[NSDictionary class]])return Json(env,@{@"error":@"请求格式无效"});return Json(env,@{@"value":Run(r)});}@catch(NSException* e){return Json(env,@{@"error":e.reason?:@"电脑操作失败"});}}}
static napi_value OCR(napi_env env,napi_callback_info info){@autoreleasepool{size_t n=1;napi_value arg;napi_get_cb_info(env,info,&n,&arg,nullptr,nullptr);void* data=nullptr;size_t len=0;if(napi_get_buffer_info(env,arg,&data,&len)!=napi_ok)return Json(env,@{@"error":@"图片无效"});NSData* bytes=[NSData dataWithBytes:data length:len];VNRecognizeTextRequest* request=[VNRecognizeTextRequest new];request.recognitionLanguages=@[@"zh-Hans",@"en-US"];request.recognitionLevel=VNRequestTextRecognitionLevelAccurate;NSError* error=nil;VNImageRequestHandler* handler=[[VNImageRequestHandler alloc]initWithData:bytes options:@{}];if(![handler performRequests:@[request] error:&error])return Json(env,@{@"error":error.localizedDescription?:@"文字识别失败"});NSMutableArray* lines=[NSMutableArray array];for(VNRecognizedTextObservation* result in request.results){VNRecognizedText* text=[result topCandidates:1].firstObject;if(text)[lines addObject:@{@"text":text.string,@"x":@(result.boundingBox.origin.x),@"y":@(1-result.boundingBox.origin.y-result.boundingBox.size.height),@"width":@(result.boundingBox.size.width),@"height":@(result.boundingBox.size.height)}];}return Json(env,@{@"value":lines});}}
static napi_value Init(napi_env env,napi_value exports){napi_property_descriptor p[]={{"request",nullptr,Request,nullptr,nullptr,nullptr,napi_default,nullptr},{"ocr",nullptr,OCR,nullptr,nullptr,nullptr,napi_default,nullptr}};napi_define_properties(env,exports,2,p);return exports;}
